import Foundation

/// Logical role of each Word style used by the export (the intended style
/// mapping table). The `rawValue` is the EXACT styleId of the author's real
/// Word template (verified by unpacking it read-only; the ids are Italian
/// because that template is in Italian). The built-in template generated by
/// the app (`defaultStylesXML`/`defaultNumberingXML` below) DELIBERATELY uses
/// the same ids, so a `w:pStyle` block written by `RewriteDocxExporter` is
/// identical whether the export uses the user's chosen template or the
/// built-in one ("the same styleId").
enum RewriteDocxStyle: String, CaseIterable, Sendable {
    case normal = "Normal"
    case title = "Title"
    case subtitle = "Subtitle"
    case heading1 = "Heading1"
    case heading2 = "Heading2"
    case heading3 = "Heading3"
    case heading4 = "Heading4"
    case point = "Puntoelenco"
    case subpoint = "Sub-puntoelenco"
    case explanation = "Spiegazionebullet"
    case note = "Nota"
    case formula = "Formula"
    case consequence = "Conseguenza"
    /// styleId `GrassoTitoli` ("Grasso Titoli"): a rare subheading, not in the
    /// contents. The current template writes it with capitals (it used to be
    /// `grassotitoli`): the `rawValue` is the styleId of the CURRENT template,
    /// and `RewriteDocxStyle.lookupKeys` still finds the old spelling too.
    case subheading = "GrassoTitoli"
    /// styleId `Definizione` ("Definizione"), new in the updated template:
    /// the definition line (`RewriteLineType.definition`).
    case definition = "Definizione"
    /// styleId `Example` ("Example"), new in the updated template: the example
    /// line (`RewriteLineType.example`).
    case example = "Example"
    /// CHARACTER style (not paragraph) for the "Emphasise marked terms" option
    /// (off by default). `IntenseEmphasis` is a BUILT-IN Word style (verified
    /// in the author's real template: present, built-in, not
    /// `w:customStyle`), so a marked run references
    /// `<w:rStyle w:val="IntenseEmphasis"/>` instead of writing `<w:b/>`
    /// directly (never direct bold). Injected silently if absent (app
    /// scaffolding for an option the user can turn on, not part of the
    /// intended style mapping table; the same silent treatment as
    /// `normal`/`title`/`subtitle`, `RewriteDocxTemplateStore`).
    case markedTerm = "IntenseEmphasis"

    /// Subset of the intended style mapping table: if one of these is missing
    /// from the chosen template, the export reports it
    /// (`RewriteDocxTemplateStore.Resolved.fallbacksUsed`). Excludes
    /// `heading4` (its own rule: T4 without Heading4 falls back to Heading3,
    /// no patch) and `normal`/`title`/`subtitle` (app scaffolding, never part
    /// of the requested mapping; injected silently if really missing, never
    /// reported).
    static let reportableStyles: [RewriteDocxStyle] = [
        .heading1, .heading2, .heading3, .point, .subpoint, .explanation, .note, .formula, .consequence, .subheading,
        .definition, .example,
    ]

    /// Visible name of the style in Word's Styles pane (`w:name`) in the
    /// built-in template and in the author's current one.
    var defaultName: String {
        switch self {
        case .normal: "Normal"
        case .title: "Title"
        case .subtitle: "Subtitle"
        case .heading1: "heading 1"
        case .heading2: "heading 2"
        case .heading3: "heading 3"
        case .heading4: "heading 4"
        case .point: "Punto elenco"
        case .subpoint: "Sub-punto elenco"
        case .explanation: "Spiegazione bullet"
        case .note: "Nota"
        case .formula: "Formula"
        case .consequence: "Conseguenza"
        case .subheading: "Grasso Titoli"
        case .definition: "Definizione"
        case .example: "Example"
        case .markedTerm: "Intense Emphasis"
        }
    }

    /// `true` for the CHARACTER style (`w:type="character"`), `false` for
    /// every paragraph style: the template lookup compares only styles of the
    /// same kind (a paragraph style named "Grassetto" can never be mistaken
    /// for a character style).
    var isCharacterStyle: Bool { self == .markedTerm }

    /// Comparison "by name as well as by identifier, ignoring case, spaces
    /// and hyphens": `GrassoTitoli`, `grassotitoli` and "Grasso Titoli" give
    /// the same key.
    static func lookupKey(_ text: String) -> String {
        let folded = text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: nil)
        return String(folded.unicodeScalars.filter { scalar in
            !CharacterSet.whitespacesAndNewlines.contains(scalar) && !"-_\u{2010}\u{2011}\u{2012}\u{2013}\u{2014}".unicodeScalars.contains(scalar)
        })
    }

    /// Keys by which a role is recognized in a template (styleId or name).
    var lookupKeys: Set<String> {
        [Self.lookupKey(rawValue), Self.lookupKey(defaultName)]
    }

    static func style(for lineType: RewriteLineType) -> RewriteDocxStyle {
        switch lineType {
        case .point, .other: .point
        case .subpoint: .subpoint
        case .explanation: .explanation
        case .note: .note
        case .formula: .formula
        case .consequence: .consequence
        case .subheading: .subheading
        case .definition: .definition
        case .example: .example
        }
    }
}

/// BUILT-IN Word template ("the built-in template has the same styleIds and
/// is generated by the app"). It also generates the individual
/// `<w:style>`/numbering fragments used by `RewriteDocxTemplateStore` to
/// "patch" a user-chosen template that lacks one of these styles ("missing
/// style -> nearest built-in style, reported").
///
/// Reserved `numId`s (9001/9002) for point+sub-point and consequence: never
/// used by a real styleId read from a real template (real templates use
/// small consecutive integers, verified on the author's template: numId
/// 1-10). This avoids any collision without having to merge/renumber the
/// numbering already present in the chosen template.
enum RewriteDocxDefaultTemplate {
    private static let pointSubpointNumId = 9001
    private static let consequenceNumId = 9002
    /// Reserved as above, but ALWAYS included (not a "patch" tied to one of the
    /// mapped styleIds): it is only needed by `RewriteExportNode.steps`, a
    /// line type kept for compatibility with an analysis saved before the
    /// outline format (`kind == .steps`), foreign to the style mapping table;
    /// no template, chosen or built-in, defines it by itself.
    static let stepsNumId = 9003
    /// Styleid "List Paragraph", a Word built-in: like `stepsNumId`, always
    /// included rather than tied to its presence in the chosen template, used
    /// only by the `steps`/`table` lines of a pre-outline analysis.
    static let listParagraphStyleId = "ListParagraph"

    // MARK: - Styles (one fragment per styleId, concatenated for the built-in template)

    private static func styleXML(_ style: RewriteDocxStyle) -> String {
        switch style {
        case .normal:
            return #"<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/></w:style>"#
        case .title:
            return #"<w:style w:type="paragraph" w:styleId="Title"><w:name w:val="Title"/><w:basedOn w:val="Normal"/><w:rPr><w:b/><w:sz w:val="40"/></w:rPr></w:style>"#
        case .subtitle:
            return #"<w:style w:type="paragraph" w:styleId="Subtitle"><w:name w:val="Subtitle"/><w:basedOn w:val="Normal"/><w:rPr><w:i/><w:sz w:val="20"/></w:rPr></w:style>"#
        case .heading1:
            return #"<w:style w:type="paragraph" w:styleId="Heading1"><w:name w:val="heading 1"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:outlineLvl w:val="0"/></w:pPr><w:rPr><w:b/><w:sz w:val="32"/></w:rPr></w:style>"#
        case .heading2:
            return #"<w:style w:type="paragraph" w:styleId="Heading2"><w:name w:val="heading 2"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:outlineLvl w:val="1"/></w:pPr><w:rPr><w:b/><w:sz w:val="28"/></w:rPr></w:style>"#
        case .heading3:
            return #"<w:style w:type="paragraph" w:styleId="Heading3"><w:name w:val="heading 3"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:outlineLvl w:val="2"/></w:pPr><w:rPr><w:b/><w:sz w:val="24"/></w:rPr></w:style>"#
        case .heading4:
            return #"<w:style w:type="paragraph" w:styleId="Heading4"><w:name w:val="heading 4"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:outlineLvl w:val="3"/></w:pPr><w:rPr><w:b/><w:i/><w:sz w:val="22"/></w:rPr></w:style>"#
        case .point:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Puntoelenco"><w:name w:val="Punto elenco"/><w:basedOn w:val="Normal"/><w:pPr><w:numPr><w:numId w:val="\#(pointSubpointNumId)"/></w:numPr></w:pPr></w:style>"#
        case .subpoint:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Sub-puntoelenco"><w:name w:val="Sub-punto elenco"/><w:basedOn w:val="Normal"/><w:pPr><w:numPr><w:ilvl w:val="1"/><w:numId w:val="\#(pointSubpointNumId)"/></w:numPr><w:spacing w:before="80"/></w:pPr></w:style>"#
        case .explanation:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Spiegazionebullet"><w:name w:val="Spiegazione bullet"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:spacing w:line="240" w:lineRule="auto"/></w:pPr><w:rPr><w:i/><w:iCs/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:style>"#
        case .note:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Nota"><w:name w:val="Nota"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:pBdr><w:left w:val="single" w:sz="24" w:space="4" w:color="FFC000"/></w:pBdr><w:ind w:left="284"/></w:pPr></w:style>"#
        case .formula:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Formula"><w:name w:val="Formula"/><w:basedOn w:val="Normal"/><w:pPr><w:pBdr><w:top w:val="single" w:sz="18" w:space="1" w:color="156082"/><w:left w:val="single" w:sz="18" w:space="4" w:color="156082"/><w:bottom w:val="single" w:sz="18" w:space="1" w:color="156082"/><w:right w:val="single" w:sz="18" w:space="4" w:color="156082"/></w:pBdr><w:spacing w:before="240" w:after="240"/><w:jc w:val="center"/></w:pPr><w:rPr><w:i/><w:iCs/></w:rPr></w:style>"#
        case .consequence:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Conseguenza"><w:name w:val="Conseguenza"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:numPr><w:numId w:val="\#(consequenceNumId)"/></w:numPr></w:pPr></w:style>"#
        case .definition:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Definizione"><w:name w:val="Definizione"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:pBdr><w:left w:val="single" w:sz="24" w:space="4" w:color="156082"/></w:pBdr><w:ind w:left="284"/></w:pPr></w:style>"#
        case .example:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="Example"><w:name w:val="Example"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:pBdr><w:left w:val="single" w:sz="24" w:space="4" w:color="3A3A3A"/></w:pBdr><w:ind w:left="284"/></w:pPr><w:rPr><w:i/><w:iCs/><w:color w:val="3A3A3A"/><w:sz w:val="20"/></w:rPr></w:style>"#
        case .subheading:
            return #"<w:style w:type="paragraph" w:customStyle="1" w:styleId="GrassoTitoli"><w:name w:val="Grasso Titoli"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:pPr><w:spacing w:before="40"/></w:pPr><w:rPr><w:b/><w:bCs/></w:rPr></w:style>"#
        case .markedTerm:
            return #"<w:style w:type="character" w:customStyle="1" w:styleId="IntenseEmphasis"><w:name w:val="Intense Emphasis"/><w:rPr><w:b/></w:rPr></w:style>"#
        }
    }

    /// Built-in `<w:style>` fragment for a styleId missing from the template
    /// the user chose (`RewriteDocxTemplateStore`, "missing style -> nearest
    /// built-in style").
    static func fallbackStyleXML(for style: RewriteDocxStyle) -> String {
        styleXML(style)
    }

    // MARK: - Numbering (only point/sub-point/consequence need it)

    /// Built-in `<w:abstractNum>`/`<w:num>` fragment for the given styleId,
    /// `nil` if that style uses no numbering (note/formula/subheading/
    /// headings/normal/title: no list).
    static func fallbackNumberingXML(for style: RewriteDocxStyle) -> String? {
        switch style {
        case .point, .subpoint:
            return """
            <w:abstractNum w:abstractNumId="\(pointSubpointNumId)">
            <w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="bullet"/><w:lvlText w:val="•"/><w:pPr><w:ind w:left="680" w:hanging="340"/></w:pPr><w:rPr><w:rFonts w:ascii="Symbol" w:hAnsi="Symbol" w:hint="default"/></w:rPr></w:lvl>
            <w:lvl w:ilvl="1"><w:start w:val="1"/><w:numFmt w:val="bullet"/><w:lvlText w:val="o"/><w:pPr><w:ind w:left="1106" w:hanging="340"/></w:pPr><w:rPr><w:rFonts w:ascii="Courier New" w:hAnsi="Courier New" w:hint="default"/></w:rPr></w:lvl>
            </w:abstractNum>
            <w:num w:numId="\(pointSubpointNumId)"><w:abstractNumId w:val="\(pointSubpointNumId)"/></w:num>
            """
        case .consequence:
            return """
            <w:abstractNum w:abstractNumId="\(consequenceNumId)">
            <w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="bullet"/><w:lvlText w:val="→"/><w:pPr><w:ind w:left="680" w:hanging="340"/></w:pPr></w:lvl>
            </w:abstractNum>
            <w:num w:numId="\(consequenceNumId)"><w:abstractNumId w:val="\(consequenceNumId)"/></w:num>
            """
        default:
            return nil
        }
    }

    /// `<w:abstractNum>`/`<w:num>` for `steps` (ALWAYS included, see
    /// `stepsNumId` above): a numbered list "1.", "2." ..., with no link to
    /// the mapped styles.
    static let stepsNumberingXML = """
    <w:abstractNum w:abstractNumId="\(stepsNumId)">
    <w:lvl w:ilvl="0"><w:start w:val="1"/><w:numFmt w:val="decimal"/><w:lvlText w:val="%1."/><w:pPr><w:ind w:left="720" w:hanging="360"/></w:pPr></w:lvl>
    </w:abstractNum>
    <w:num w:numId="\(stepsNumId)"><w:abstractNumId w:val="\(stepsNumId)"/></w:num>
    """

    /// `<w:style>` "List Paragraph" (ALWAYS included, see
    /// `listParagraphStyleId` above).
    static let listParagraphStyleXML = #"<w:style w:type="paragraph" w:styleId="ListParagraph"><w:name w:val="List Paragraph"/><w:basedOn w:val="Normal"/></w:style>"#

    // MARK: - Complete built-in template (no template chosen in Settings)

    static let defaultStylesXML: String = {
        let body = RewriteDocxStyle.allCases.map(styleXML).joined() + listParagraphStyleXML
        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
        <w:docDefaults><w:rPrDefault><w:rPr><w:sz w:val="23"/></w:rPr></w:rPrDefault></w:docDefaults>
        \(body)
        </w:styles>
        """
    }()

    static let defaultNumberingXML: String = {
        let fragments = [
            fallbackNumberingXML(for: .point),
            fallbackNumberingXML(for: .consequence),
        ].compactMap { $0 }.joined() + stepsNumberingXML
        return """
        <?xml version="1.0" encoding="UTF-8" standalone="yes"?>
        <w:numbering xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
        \(fragments)
        </w:numbering>
        """
    }()
}
